import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import { ChevronDown, ChevronUp, Brain } from "lucide-react";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  ResponsiveContainer,
} from "recharts";
import type { Result } from "@/pages/Index";
import { cn } from "@/lib/utils";

interface ConfidenceReportProps {
  results: Result[];
}

interface BucketEntry {
  label: string;
  count: number;
  range: string;
}

const getConfidenceBadge = (
  avg: number
): { label: string; variant: "default" | "secondary" | "destructive" | "outline" } => {
  if (avg >= 75) return { label: "High", variant: "default" };
  if (avg >= 45) return { label: "Medium", variant: "secondary" };
  return { label: "Low", variant: "destructive" };
};

const ConfidenceReport = ({ results }: ConfidenceReportProps) => {
  const [open, setOpen] = useState(false);

  const scored = results.filter((r) => !r.pending && r.overall_score > 0);
  if (scored.length === 0) return null;

  // 1. Overall AI Confidence
  const avgConfidence = Math.round(
    scored.reduce((sum, r) => sum + (r.confidence ?? 0), 0) / scored.length
  );

  // 2. Per-Dimension averages from category_scores_json
  const dimensionTotals: Record<string, { total: number; count: number }> = {};
  for (const r of scored) {
    if (!r.category_scores_json || typeof r.category_scores_json !== "object") continue;
    for (const [key, val] of Object.entries(
      r.category_scores_json as Record<string, { score: number }>
    )) {
      if (!dimensionTotals[key]) dimensionTotals[key] = { total: 0, count: 0 };
      dimensionTotals[key].total += val.score ?? 0;
      dimensionTotals[key].count += 1;
    }
  }
  const dimensions = Object.entries(dimensionTotals).map(([name, { total, count }]) => ({
    name,
    avg: Math.round(total / count),
  }));

  // 3. Score distribution buckets
  const buckets: BucketEntry[] = [
    { label: "Weak", range: "0–25%", count: 0 },
    { label: "Below Avg", range: "26–50%", count: 0 },
    { label: "Good", range: "51–75%", count: 0 },
    { label: "Strong", range: "76–100%", count: 0 },
  ];
  for (const r of scored) {
    const s = r.overall_score;
    if (s <= 25) buckets[0].count++;
    else if (s <= 50) buckets[1].count++;
    else if (s <= 75) buckets[2].count++;
    else buckets[3].count++;
  }
  const chartData = buckets.map((b) => ({ name: b.label, count: b.count, range: b.range }));

  const { label: confidenceLabel, variant: confidenceVariant } = getConfidenceBadge(avgConfidence);

  const formatDimensionName = (key: string) =>
    key
      .replace(/_/g, " ")
      .replace(/\b\w/g, (c) => c.toUpperCase());

  return (
    <Collapsible open={open} onOpenChange={setOpen}>
      <Card>
        <CollapsibleTrigger asChild>
          <CardHeader className="pb-3 cursor-pointer select-none hover:bg-muted/30 transition-colors rounded-t-lg">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <div className="w-7 h-7 rounded-md bg-primary/10 flex items-center justify-center shrink-0">
                  <Brain className="h-4 w-4 text-primary" />
                </div>
                <CardTitle className="text-base">AI Confidence Score</CardTitle>
                <Badge variant={confidenceVariant} className="text-[10px] px-1.5 py-0">
                  {confidenceLabel}
                </Badge>
              </div>
              <div className="flex items-center gap-3">
                <span className="text-sm font-semibold tabular-nums text-primary">
                  {avgConfidence}/100
                </span>
                {open ? (
                  <ChevronUp className="h-4 w-4 text-muted-foreground" />
                ) : (
                  <ChevronDown className="h-4 w-4 text-muted-foreground" />
                )}
              </div>
            </div>
          </CardHeader>
        </CollapsibleTrigger>

        <CollapsibleContent>
          <CardContent className="pt-0 space-y-6">
            {/* Overall confidence bar */}
            <div className="space-y-1.5">
              <div className="flex items-center justify-between text-xs text-muted-foreground">
                <span>Average AI confidence across {scored.length} candidate{scored.length !== 1 ? "s" : ""}</span>
                <span className="font-medium text-foreground tabular-nums">{avgConfidence}%</span>
              </div>
              <Progress value={avgConfidence} className="h-2" />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* Per-Dimension scores */}
              {dimensions.length > 0 && (
                <div className="space-y-3">
                  <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">
                    Scoring Dimensions
                  </p>
                  <div className="space-y-2.5">
                    {dimensions.map((dim) => (
                      <div key={dim.name} className="space-y-1">
                        <div className="flex items-center justify-between">
                          <span className="text-xs font-medium text-foreground">
                            {formatDimensionName(dim.name)}
                          </span>
                          <span
                            className={cn(
                              "text-xs font-semibold tabular-nums",
                              dim.avg >= 70
                                ? "text-score-skills"
                                : dim.avg >= 40
                                ? "text-warning"
                                : "text-destructive"
                            )}
                          >
                            {dim.avg}%
                          </span>
                        </div>
                        <div className="h-1.5 rounded-full bg-secondary overflow-hidden">
                          <div
                            className={cn(
                              "h-full rounded-full transition-all duration-500",
                              dim.avg >= 70
                                ? "bg-score-skills"
                                : dim.avg >= 40
                                ? "bg-warning"
                                : "bg-destructive"
                            )}
                            style={{ width: `${Math.min(dim.avg, 100)}%` }}
                          />
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* Score Distribution Chart */}
              <div className="space-y-3">
                <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">
                  Score Distribution
                </p>
                <div className="h-36">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart
                      data={chartData}
                      margin={{ top: 4, right: 4, left: -20, bottom: 0 }}
                    >
                      <XAxis
                        dataKey="name"
                        tick={{ fontSize: 10, fill: "hsl(var(--muted-foreground))" }}
                        axisLine={false}
                        tickLine={false}
                      />
                      <YAxis
                        allowDecimals={false}
                        tick={{ fontSize: 10, fill: "hsl(var(--muted-foreground))" }}
                        axisLine={false}
                        tickLine={false}
                        width={28}
                      />
                      <Tooltip
                        cursor={{ fill: "hsl(var(--muted))" }}
                        contentStyle={{
                          background: "hsl(var(--card))",
                          border: "1px solid hsl(var(--border))",
                          borderRadius: "6px",
                          fontSize: "12px",
                          padding: "6px 10px",
                        }}
                        formatter={(value: number, _name: string, props: any) => [
                          `${value} candidate${value !== 1 ? "s" : ""}`,
                          props.payload?.range ?? "",
                        ]}
                        labelFormatter={(label) => label}
                      />
                      <Bar
                        dataKey="count"
                        radius={[4, 4, 0, 0]}
                        fill="hsl(var(--primary))"
                        maxBarSize={48}
                      />
                    </BarChart>
                  </ResponsiveContainer>
                </div>
                {/* Bucket breakdown as compact text */}
                <div className="grid grid-cols-2 gap-1.5">
                  {buckets.map((b) => (
                    <div
                      key={b.label}
                      className="flex items-center justify-between rounded-md bg-muted/50 px-2.5 py-1.5"
                    >
                      <span className="text-[11px] text-muted-foreground">{b.label}</span>
                      <span className="text-[11px] font-semibold tabular-nums text-foreground">
                        {b.count}
                      </span>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </CardContent>
        </CollapsibleContent>
      </Card>
    </Collapsible>
  );
};

export default ConfidenceReport;

